begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Synthetic actors and assessments only. Test signer is transaction-local.
insert into auth.users(id,email) values ('b4000000-0000-4000-8000-000000000021','controlled-a@elifora.test'),('b4000000-0000-4000-8000-000000000022','controlled-b@elifora.test');
insert into public.organizations(id,name,slug,base_currency) values ('b4000000-0000-4000-8000-000000000001','Controlled A','controlled-a','TRY'),('b4000000-0000-4000-8000-000000000002','Controlled B','controlled-b','TRY');
insert into public.locations(id,organization_id,name,timezone) values ('b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000001','A','Europe/Istanbul'),('b4000000-0000-4000-8000-000000000012','b4000000-0000-4000-8000-000000000002','B','Europe/Istanbul');
insert into public.salon_memberships(id,organization_id,location_id,user_id,role_code,status,joined_at) values ('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000021','owner','active',now()),('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000002','b4000000-0000-4000-8000-000000000012','b4000000-0000-4000-8000-000000000022','owner','active',now());
insert into public.clients(id,organization_id,full_name,phone,phone_normalized,created_by,updated_by,creation_location_id) values ('b4000000-0000-4000-8000-000000000031','b4000000-0000-4000-8000-000000000001','Synthetic controlled client','+905329998877','+905329998877','b4000000-0000-4000-8000-000000000021','b4000000-0000-4000-8000-000000000021','b4000000-0000-4000-8000-000000000011');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
set local role elifora_hair_writer;
insert into public.hair_passports(id,organization_id,client_id) values ('b4000000-0000-4000-8000-000000000041','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000031');
insert into public.hair_regions(id,organization_id,client_id,passport_id,region_type) values ('b4000000-0000-4000-8000-000000000051','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000031','b4000000-0000-4000-8000-000000000041','ROOT');
insert into public.hair_evidence(id,organization_id,client_id,passport_id,source_type,observed_at_state,observed_at,verified_by) values ('b4000000-0000-4000-8000-000000000061','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000031','b4000000-0000-4000-8000-000000000041','PROFESSIONAL_VERIFIED','KNOWN',now(),'b4000000-0000-4000-8000-000000000021');
insert into public.hair_observations(id,organization_id,client_id,passport_id,region_id,evidence_id,grey_ratio_state,grey_ratio) values ('b4000000-0000-4000-8000-000000000071','b4000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000031','b4000000-0000-4000-8000-000000000041','b4000000-0000-4000-8000-000000000051','b4000000-0000-4000-8000-000000000061','KNOWN',.9);
update public.hair_regions set current_observation_id='b4000000-0000-4000-8000-000000000071' where id='b4000000-0000-4000-8000-000000000051';
reset role;
insert into app_private.catalog_operators(user_id) values(auth.uid());
create temporary table result(name text primary key,value jsonb);
grant all on result to authenticated;
insert into result values('catalog',public.catalog_governance('IMPORT',null,'Synthetic fixture review',gen_random_uuid()));
select public.catalog_governance(op,(select (value->>'catalogId')::uuid from result where name='catalog'),'Synthetic fixture review',gen_random_uuid()) from unnest(array['START_REVIEW','COMPLETE_REVIEW','VALIDATE_GOLDEN','APPROVE','PUBLISH']) op;
create function pg_temp.sign(v jsonb) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('envelope',v::text,'signature',encode(extensions.hmac(convert_to(v::text,'UTF8'),secret,'sha256'),'hex')) from app_private.color_engine_keys where id=1;$$;
create function pg_temp.plan(op text,v jsonb) returns jsonb language sql volatile as $$select public.color_plan_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000031',op,v,gen_random_uuid());$$;
create function pg_temp.store(v jsonb) returns jsonb language sql volatile as $$select public.controlled_recipe_store('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011',pg_temp.sign(v)->>'envelope',pg_temp.sign(v)->>'signature',gen_random_uuid());$$;
set local role authenticated;
insert into result values('target',public.color_target_operation('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','b4000000-0000-4000-8000-000000000031','create',jsonb_build_object('request_id',gen_random_uuid(),'definition',jsonb_build_object('schemaVersion',1,'mode','ROOT_REFRESH','globalIntent','REFRESH','regions',jsonb_build_array(jsonb_build_object('regionId','b4000000-0000-4000-8000-000000000051','level',8,'toneFamily','NEUTRAL','mixedFamilies','[]'::jsonb,'warmth','NEUTRAL','greyPriority','NONE','liftPriority','NONE','depositPriority','NORMAL','toneIntent','CHANGE','contrast','NONE','preserve',false,'handling','STANDARD','correction','NONE','intermediateLevel',null)))),gen_random_uuid()));
insert into result values('prepare',pg_temp.plan('prepare',jsonb_build_object('target_id',(select value#>>'{data,id}' from result where name='target'),'request_id','b4000000-0000-4000-8000-000000000602')));
-- A test-signed minimal progressing Color Plan tests the DB boundary independently
-- of the real TS engine, which is exercised through real Auth in the browser suite.
insert into result values('planPacket',(select jsonb_build_object('organizationId','b4000000-0000-4000-8000-000000000001','actorId','b4000000-0000-4000-8000-000000000021','membershipId','b4000000-0000-4000-8000-000000000111','locationId','b4000000-0000-4000-8000-000000000011','clientId','b4000000-0000-4000-8000-000000000031','targetId',value#>>'{data,target,id}','requestId','b4000000-0000-4000-8000-000000000602','sourceToken',value#>>'{data,sourceToken}','expiresAt',statement_timestamp()+interval '2 minutes','result',jsonb_build_object('engineVersion','color-engine/1.0.0','evaluatedAt',statement_timestamp(),'status','DRAFT','safetyGate',jsonb_build_object('canProgress',true),'primaryStrategy','{}'::jsonb,'alternatives','[]'::jsonb,'recipeDraft',jsonb_build_object('id',repeat('d',64),'version',1,'parentVersionId',null,'origin','ENGINE','executionStatus','REQUIRES_BRAND_ADAPTER'),'metadata',jsonb_build_object('passportId',value#>>'{data,target,passportId}','passportVersion',(value#>>'{data,snapshot,pages,0,passport,version}')::bigint,'targetId',value#>>'{data,target,id}','targetVersion',1,'inputFingerprint',repeat('a',64),'hairFingerprint',repeat('b',64),'targetFingerprint',repeat('c',64),'confidenceVersion','confidence-engine/1.0.0','riskVersion','risk-engine/1.0.0'))) from result where name='prepare'));
insert into result values('plan',pg_temp.plan('store',pg_temp.sign((select value from result where name='planPacket'))));
select ok((select value#>>'{data,id}' is not null from result where name='plan'),'test-signed plan fixture persisted');
reset role;
insert into result values('packet',public.catalog_pilot_packet((select (value->>'catalogId')::uuid from result where name='catalog')));
create temporary table chosen as select p.id product_id,d.id developer_id,r.id rule_id from public.catalog_products p,public.catalog_products d,public.catalog_compatibility_rules r where p.catalog_id=(select (value->>'catalogId')::uuid from result where name='catalog') and p.manufacturer_code='8-01' and d.catalog_id=p.catalog_id and d.manufacturer_code='IGORA ROYAL OIL DEVELOPER 9%' and r.product_id=p.id and r.developer_id=d.id;
grant select on chosen to authenticated;
select is((select count(*) from chosen),1::bigint,'one exact source-backed pair selected');
insert into result values('envelope',(select jsonb_build_object('organizationId','b4000000-0000-4000-8000-000000000001','actorId','b4000000-0000-4000-8000-000000000021','membershipId','b4000000-0000-4000-8000-000000000111','locationId','b4000000-0000-4000-8000-000000000011','sourceToken',(select value#>>'{data,sourceToken}' from result where name='prepare'),'expiresAt',statement_timestamp()+interval '2 minutes','input',jsonb_build_object('request_id','b4000000-0000-4000-8000-000000000701','client_id','b4000000-0000-4000-8000-000000000031','plan_id',(select value#>>'{data,id}' from result where name='plan'),'catalog_id',value#>>'{catalog,release,id}','product_id',chosen.product_id,'developer_id',chosen.developer_id,'color_grams',30.15,'supersedes_id',null),'result',jsonb_build_object('schemaVersion',3,'engineVersion','controlled-brand-recipe/1.0.0','state','DRAFT_FOR_PROFESSIONAL_REVIEW','executable',false,'professionalReviewRequired',true,'selectionOrigin','PROFESSIONAL_INPUT','amountBasis','USER_ENTERED_COLOR_GRAMS','parentRecipeId',repeat('d',64),'colorGrams',30.15,'developerGrams',30.15,'totalGrams',60.30,'context',jsonb_build_object('regionId','b4000000-0000-4000-8000-000000000051','whiteRatio',.9,'evidenceIds',jsonb_build_array('b4000000-0000-4000-8000-000000000061')),'sources',value->'sources','snapshots',jsonb_build_object('catalogId',value#>>'{catalog,release,id}','catalogVersion',1,'catalogFingerprint',value#>>'{catalog,release,versionFingerprint}','productVersion',1,'developerVersion',1,'ruleVersion',1),'selected',jsonb_build_object('productId',chosen.product_id,'developerId',chosen.developer_id,'compatibilityRuleId',chosen.rule_id,'mixingRatio','1:1','executable',false,'sourceIds',(select jsonb_agg(x->'id') from jsonb_array_elements(value->'sources') x)))) from result,chosen where name='packet'));
set local role authenticated;
select is(public.controlled_recipe_store('b4000000-0000-4000-8000-000000000111','b4000000-0000-4000-8000-000000000011','{}',repeat('0',64),gen_random_uuid())->>'code','COLOR_PLAN_SIGNATURE_INVALID','unsigned quantity/result cannot persist');
insert into result values('v1',pg_temp.store((select value from result where name='envelope')));
select ok((select value->>'id' is not null from result where name='v1'),'authenticated signed controlled recipe saved');
select is((select value#>>'{result,totalGrams}' from result where name='v1'),'60.30','documented arithmetic retained as exact numeric');
select is((select value->>'version' from result where name='v1'),'1','new recipe series starts at version one');
select is(pg_temp.store((select value from result where name='envelope'))->>'id',(select value->>'id' from result where name='v1'),'identical retry returns the same immutable result');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{input,color_grams}','31'))->>'code','CONTROLLED_RECIPE_VERSION_CONFLICT','same request cannot change professional amount');
select throws_ok('insert into public.controlled_brand_recipes default values','42501',null,'client cannot forge recipe ownership');
select throws_ok('update public.controlled_brand_recipes set executable=true','42501',null,'client cannot enable chemical execution');
select ok(not has_function_privilege('anon','public.controlled_recipe_store(uuid,uuid,text,text,uuid)','EXECUTE'),'anonymous signed store denied');
select ok(not has_function_privilege('service_role','public.controlled_recipe_store(uuid,uuid,text,text,uuid)','EXECUTE'),'service role cannot generate recipes');
update result set value=jsonb_set(value,'{input,request_id}',to_jsonb(gen_random_uuid()::text)) where name='envelope';
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{result,context,whiteRatio}','0.8'))->>'code','CONTROLLED_RECIPE_CONTEXT_INVALID','white ratio must match actual professional evidence');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{result,developerGrams}','31'))->>'code','VALIDATION_FAILED','signed wrong ratio arithmetic still rejected by DB');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{result,executable}','true'))->>'code','VALIDATION_FAILED','even a signed recipe cannot become executable');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{result,sources}','[]'))->>'code','CONTROLLED_RECIPE_CONTEXT_INVALID','missing source provenance blocked');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{sourceToken}',to_jsonb(repeat('0',64))))->>'code','COLOR_PLAN_SOURCE_CONFLICT','stale source token forces reassessment');
select is(pg_temp.store(jsonb_set((select value from result where name='envelope'),'{expiresAt}',to_jsonb((statement_timestamp()-interval '1 minute')::text)))->>'code','TENANT_CONTEXT_INVALID','expired signed calculation blocked');
update result set value=jsonb_set(value,'{input,supersedes_id}',(select value->'id' from result where name='v1')) where name='envelope';
insert into result values('v2',pg_temp.store((select value from result where name='envelope')));
select is((select value->>'version' from result where name='v2'),'2','edit creates next immutable version');
select is((select value->>'seriesId' from result where name='v2'),(select value->>'seriesId' from result where name='v1'),'lineage retained');
update result set value=jsonb_set(value,'{input,request_id}',to_jsonb(gen_random_uuid()::text)) where name='envelope';
select is(pg_temp.store((select value from result where name='envelope'))->>'code','CONTROLLED_RECIPE_VERSION_CONFLICT','concurrent stale parent cannot fork history');
select is((select count(*) from public.controlled_brand_recipes),2::bigint,'own tenant sees complete versions');
reset role;
select is((select count(*) from public.audit_events where action='controlled_recipe.created'),2::bigint,'one audit per committed version; no retry audit');
select throws_ok('update public.controlled_brand_recipes set color_grams=1','23514','IMMUTABLE_CONTROLLED_RECIPE','maintenance cannot rewrite historical quantity');
select throws_ok('delete from public.controlled_brand_recipes','23514','IMMUTABLE_CONTROLLED_RECIPE','history cannot be deleted');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);
set local role authenticated;
select is((select count(*) from public.controlled_brand_recipes),0::bigint,'cross tenant history concealed by RLS');
select is(pg_temp.store((select value from result where name='envelope'))->>'code','TENANT_CONTEXT_INVALID','foreign actor cannot reuse signed owner envelope');
reset role;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
update public.salon_memberships set status='revoked',revoked_at=now() where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select is((select count(*) from public.controlled_brand_recipes),0::bigint,'revoked member immediately loses recipe history');
reset role;
set local role anon;
select throws_ok('select * from public.controlled_brand_recipes','42501',null,'anonymous history read denied');
reset role;
select * from finish();
rollback;
